import pandas as pd
import numpy as np
import warnings

# Example 1: Large integer to string column
try:
    df = pd.DataFrame({"a": ["x", "y", "z"]})
    df.loc[3] = [2**70]
    probe("df = pd.DataFrame({\"a\": [\"x\", \"y\", \"z\"]}); df.loc[3] = [2**70]", {
        "dtype": str(df["a"].dtype),
        "values": df["a"].tolist(),
        "isna": df["a"].isna().tolist()
    })
except Exception as e:
    probe("df = pd.DataFrame({\"a\": [\"x\", \"y\", \"z\"]}); df.loc[3] = [2**70]", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: NaN to SparseArray (first occurrence)
try:
    df = pd.DataFrame({"a": pd.arrays.SparseArray([0, 1, 2], fill_value=0)})
    df.loc[3] = [np.nan]
    probe("df = pd.DataFrame({\"a\": pd.arrays.SparseArray([0, 1, 2], fill_value=0)}); df.loc[3] = [np.nan]", {
        "dtype": str(df["a"].dtype),
        "isna": df["a"].isna().tolist(),
        "values": df["a"].tolist()
    })
except Exception as e:
    probe("df = pd.DataFrame({\"a\": pd.arrays.SparseArray([0, 1, 2], fill_value=0)}); df.loc[3] = [np.nan]", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 3: NaT to Int64 via _append_internal
try:
    df = pd.DataFrame({"a": pd.Series([1, 2], dtype="Int64")})
    ser = pd.Series([pd.NaT], index=["a"], name=2)
    result = df._append_internal(ser)
    probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"Int64\")}); ser = pd.Series([pd.NaT], index=[\"a\"], name=2); df._append_internal(ser)", {
        "dtype": str(result["a"].dtype),
        "values": result["a"].tolist(),
        "isna": result["a"].isna().tolist()
    })
except Exception as e:
    probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"Int64\")}); ser = pd.Series([pd.NaT], index=[\"a\"], name=2); df._append_internal(ser)", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 4: Period to pyarrow int64 column (only if pyarrow available)
try:
    try:
        import pyarrow
        has_pyarrow = True
    except ImportError:
        has_pyarrow = False

    if has_pyarrow:
        df = pd.DataFrame({"a": pd.Series([1, 2], dtype="int64[pyarrow]")})
        df.loc[2] = [pd.Period("2021-01-01", freq="D")]
        probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"int64[pyarrow]\")}); df.loc[2] = [pd.Period(\"2021-01-01\", freq=\"D\")]", {
            "dtype": str(df["a"].dtype),
            "values": df["a"].tolist()
        })
    else:
        probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"int64[pyarrow]\")}); df.loc[2] = [pd.Period(\"2021-01-01\", freq=\"D\")]", 
              "pyarrow not available")
except Exception as e:
    probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"int64[pyarrow]\")}); df.loc[2] = [pd.Period(\"2021-01-01\", freq=\"D\")]", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 5: NaN to SparseArray (duplicate, check isna specifically)
try:
    df = pd.DataFrame({"a": pd.arrays.SparseArray([0, 1, 2], fill_value=0)})
    df.loc[3] = [np.nan]
    probe("df = pd.DataFrame({\"a\": pd.arrays.SparseArray([0, 1, 2], fill_value=0)}); df.loc[3] = [np.nan]", 
          df["a"].isna().tolist())
except Exception as e:
    probe("df = pd.DataFrame({\"a\": pd.arrays.SparseArray([0, 1, 2], fill_value=0)}); df.loc[3] = [np.nan]", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 6: Float 3.0 to int64 column via _append_internal
try:
    df = pd.DataFrame({"a": [1, 2]})
    ser = pd.Series([3.0], index=["a"], name=2)
    result = df._append_internal(ser)
    probe("df = pd.DataFrame({\"a\": [1, 2]}); ser = pd.Series([3.0], index=[\"a\"], name=2); df._append_internal(ser)", {
        "dtype": str(result["a"].dtype),
        "values": result["a"].tolist()
    })
except Exception as e:
    probe("df = pd.DataFrame({\"a\": [1, 2]}); ser = pd.Series([3.0], index=[\"a\"], name=2); df._append_internal(ser)", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 7: 0.1 to float32 column via _append_internal
try:
    df = pd.DataFrame({"a": pd.Series([1, 2], dtype="float32")})
    ser = pd.Series([0.1], index=["a"], name=2)
    result = df._append_internal(ser)
    probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"float32\")}); ser = pd.Series([0.1], index=[\"a\"], name=2); df._append_internal(ser)", {
        "dtype": str(result["a"].dtype),
        "values": result["a"].tolist(),
        "value_at_index_2": result["a"].iloc[2]
    })
except Exception as e:
    probe("df = pd.DataFrame({\"a\": pd.Series([1, 2], dtype=\"float32\")}); ser = pd.Series([0.1], index=[\"a\"], name=2); df._append_internal(ser)", 
          "__error__: " + type(e).__name__ + ": " + str(e))

